/** The environment variable OpenHands reads its model from. */
const MODEL_ENV = "LLM_MODEL";
export class OpenhandsHarness {
    id = "openhands";
    displayName = "OpenHands";
    profile = { bin: "openhands", args: [] };
    systemPrompt = false;
    nativeAgent = false;
    confinable = false;
    build({ bin, args }, req) {
        const argv = [bin, ...args];
        if (req.prompt !== undefined)
            argv.push("--headless", `--task=${req.prompt}`);
        return { argv, ...(req.model ? { env: { [MODEL_ENV]: req.model } } : {}) };
    }
}
